function g({registerIndicator:h,sourceValues:M,nulls:N}){h({id:"oa-lsma",name:"Least Squares Moving Average (LSMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:2e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"lsma",type:"line",title:"LSMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(c,r){const u=Math.max(1,Math.floor(Number(r.period)||10)),m=M(c,r.source??"close"),o=new Array(c.length).fill(NaN);for(let e=0;e<c.length;e++){const s=m[e],f=Math.min(e+1,u);if(u<=1||f<=1){o[e]=s;continue}let n=0,a=0,p=0,d=0,l=0;for(let t=0;t<f;t++){const i=e-t>=1?m[e-t]:NaN;Number.isFinite(i)&&(n+=t,a+=i,p+=t*i,d+=t*t,l+=1)}if(l<=1){o[e]=s;continue}const y=l*d-n*n;if(y===0){o[e]=s;continue}const b=(l*p-n*a)/y;o[e]=(a-b*n)/l}return{lsma:N(o)}}})}export{g as default};
